    "py": "from graaly_academy import *\n\ndef error(loc, kind):\n    return {\"loc\": loc, \"type\": kind}\n\ndef string_field(errors, input, name, minimum, maximum):\n    if name not in input:\n        errors.append(error([name], \"missing\"))\n        return \"\"\n    value = input[name]\n    if not is_string(value):\n        errors.append(error([name], \"string_type\"))\n        return \"\"\n    if len(value) < minimum:\n        errors.append(error([name], \"string_too_short\"))\n    elif maximum is not None and len(value) > maximum:\n        errors.append(error([name], \"string_too_long\"))\n    return value\n\ndef integer_field(errors, input, name, minimum, maximum, default, strict):\n    if name not in input and default is None:\n        errors.append(error([name], \"missing\"))\n        return 0\n    value = get(input, name, default)\n    if strict and not is_integer(value):\n        errors.append(error([name], \"int_type\"))\n        return 0\n    if not is_integer(value) and value is not True and value is not False:\n        if is_string(value) and regex(\"^[+-]?[0-9]+([.]0+)?$\", value.strip()):\n            value = int(float(value))\n        else:\n            kind = \"int_parsing\" if is_string(value) else \"int_from_float\" if is_number(value) else \"int_type\"\n            errors.append(error([name], kind))\n            return 0\n    value = int(value)\n    if minimum is not None and value < minimum:\n        errors.append(error([name], \"greater_than_equal\"))\n    elif maximum is not None and value > maximum:\n        errors.append(error([name], \"less_than_equal\"))\n    return value\n\ndef forbid_extra(errors, input, allowed):\n    for key in keys(input):\n        if key not in allowed:\n            errors.append(error([key], \"extra_forbidden\"))\n    return None\n\ndef outcome(errors, value):\n    return {\"ok\": False, \"errors\": errors} if errors else {\"ok\": True, \"value\": value}\n\ndef response(status, value):\n    return {\"status\": status, \"json\": value}\n\ndef route(request, path, method):\n    if url_path(get(request, \"url\", \"/\")) != path:\n        return response(404, {\"detail\": \"Not Found\"})\n    if get(request, \"method\", \"GET\") != method:\n        return response(405, {\"detail\": \"Method Not Allowed\"})\n    return None\n\ndef request_headers(request):\n    out = {}\n    values = get(request, \"headers\", {})\n    for key in keys(values):\n        out[key.lower()] = values[key]\n    return out\n\ndef body_errors(errors):\n    out = []\n    for item in errors:\n        out.append(error([\"body\"] + item[\"loc\"], item[\"type\"]))\n    return {\"status\": 422, \"errors\": out}\n\ndef solve(input):\n    private = {\"name\": \"Alex\", \"coins\": 10, \"token\": \"internal-secret\", \"admin\": True}\n    public = {}\n    for key in [\"name\", \"coins\"]:\n        public[key] = private[key]\n    out = []\n    for request in input[\"requests\"]:\n        failure = route(request, \"/v1/me\", \"GET\")\n        out.append(failure if failure else response(200, public))\n    return out\n",
    "js": "import * as h from \"@graaly/academy\";\n\nfunction error(loc, kind) {\n    return h.object([[\"loc\", loc], [\"type\", kind]]);\n}\n\nfunction string_field(errors, input, name, minimum, maximum) {\n    let value;\n    if (h.truth(h.not_in(name, input))) {\n        h.append(errors, error([name], \"missing\"));\n        return \"\";\n    }\n    value = h.get(input, name);\n    if (h.truth(h.not(h.is_string(value)))) {\n        h.append(errors, error([name], \"string_type\"));\n        return \"\";\n    }\n    if (h.truth(h.lt(h.len(value), minimum))) {\n        h.append(errors, error([name], \"string_too_short\"));\n    } else {\n        if (h.truth((h.truth(h.ne(maximum, null)) ? h.gt(h.len(value), maximum) : h.ne(maximum, null)))) {\n            h.append(errors, error([name], \"string_too_long\"));\n        }\n    }\n    return value;\n}\n\nfunction integer_field(errors, input, name, minimum, maximum, v_default, strict) {\n    let kind, value;\n    if (h.truth((h.truth(h.not_in(name, input)) ? h.eq(v_default, null) : h.not_in(name, input)))) {\n        h.append(errors, error([name], \"missing\"));\n        return 0;\n    }\n    value = h.get(input, name, v_default);\n    if (h.truth((h.truth(strict) ? h.not(h.is_integer(value)) : strict))) {\n        h.append(errors, error([name], \"int_type\"));\n        return 0;\n    }\n    if (h.truth((h.truth(h.not(h.is_integer(value))) ? (h.truth(h.ne(value, true)) ? h.ne(value, false) : h.ne(value, true)) : h.not(h.is_integer(value))))) {\n        if (h.truth((h.truth(h.is_string(value)) ? h.regex(\"^[+-]?[0-9]+([.]0+)?$\", h.strip(value)) : h.is_string(value)))) {\n            value = h.int(h.float(value));\n        } else {\n            kind = (h.truth(h.is_string(value)) ? \"int_parsing\" : (h.truth(h.is_number(value)) ? \"int_from_float\" : \"int_type\"));\n            h.append(errors, error([name], kind));\n            return 0;\n        }\n    }\n    value = h.int(value);\n    if (h.truth((h.truth(h.ne(minimum, null)) ? h.lt(value, minimum) : h.ne(minimum, null)))) {\n        h.append(errors, error([name], \"greater_than_equal\"));\n    } else {\n        if (h.truth((h.truth(h.ne(maximum, null)) ? h.gt(value, maximum) : h.ne(maximum, null)))) {\n            h.append(errors, error([name], \"less_than_equal\"));\n        }\n    }\n    return value;\n}\n\nfunction forbid_extra(errors, input, allowed) {\n    let key;\n    const seq_1 = h.keys(input);\n    for (let index_1 = 0; index_1 < seq_1.length; ++index_1) {\n        key = seq_1[index_1];\n        if (h.truth(h.not_in(key, allowed))) {\n            h.append(errors, error([key], \"extra_forbidden\"));\n        }\n    }\n    return null;\n}\n\nfunction outcome(errors, value) {\n    return (h.truth(errors) ? h.object([[\"ok\", false], [\"errors\", errors]]) : h.object([[\"ok\", true], [\"value\", value]]));\n}\n\nfunction response(status, value) {\n    return h.object([[\"status\", status], [\"json\", value]]);\n}\n\nfunction route(request, path, method) {\n    if (h.truth(h.ne(h.url_path(h.get(request, \"url\", \"/\")), path))) {\n        return response(404, h.object([[\"detail\", \"Not Found\"]]));\n    }\n    if (h.truth(h.ne(h.get(request, \"method\", \"GET\"), method))) {\n        return response(405, h.object([[\"detail\", \"Method Not Allowed\"]]));\n    }\n    return null;\n}\n\nfunction request_headers(request) {\n    let key, out, values;\n    out = h.object([]);\n    values = h.get(request, \"headers\", h.object([]));\n    const seq_2 = h.keys(values);\n    for (let index_2 = 0; index_2 < seq_2.length; ++index_2) {\n        key = seq_2[index_2];\n        h.set(out, h.lower(key), h.get(values, key));\n    }\n    return out;\n}\n\nfunction body_errors(errors) {\n    let item, out;\n    out = [];\n    const seq_3 = errors;\n    for (let index_3 = 0; index_3 < seq_3.length; ++index_3) {\n        item = seq_3[index_3];\n        h.append(out, error(h.add([\"body\"], h.get(item, \"loc\")), h.get(item, \"type\")));\n    }\n    return h.object([[\"status\", 422], [\"errors\", out]]);\n}\n\nexport function solve(input) {\n    let failure, key, out, v_private, v_public, request;\n    v_private = h.object([[\"name\", \"Alex\"], [\"coins\", 10], [\"token\", \"internal-secret\"], [\"admin\", true]]);\n    v_public = h.object([]);\n    const seq_4 = [\"name\", \"coins\"];\n    for (let index_4 = 0; index_4 < seq_4.length; ++index_4) {\n        key = seq_4[index_4];\n        h.set(v_public, key, h.get(v_private, key));\n    }\n    out = [];\n    const seq_5 = h.get(input, \"requests\");\n    for (let index_5 = 0; index_5 < seq_5.length; ++index_5) {\n        request = seq_5[index_5];\n        failure = route(request, \"/v1/me\", \"GET\");\n        h.append(out, (h.truth(failure) ? failure : response(200, v_public)));\n    }\n    return out;\n}\n",
