    "js": "import * as h from \"@graaly/academy\";\n\nexport function solve(input) {\n    let first, last;\n    first = h.bits_op(\"or\", h.get(h.get(input, \"a\"), 0), h.get(h.get(input, \"b\"), 0));\n    last = h.bits_op(\"or\", h.get(h.get(input, \"a\"), 1), h.get(h.get(input, \"b\"), 1));\n    last = h.bits_op(\"and\", last, \"0x3f\");\n    return h.add(h.bits_count(first), h.bits_count(last));\n}\n",
