  "c-field-replace": {
    "py": "from graaly_academy import *\n\ndef solve(input):\n    width, offset = input[\"width\"], input[\"offset\"]\n    if not width or offset >= 32 or width > 32 - offset:\n        return input[\"word\"]\n    low = (1 << width) - 1\n    mask = low << offset\n    return (input[\"word\"] & ~mask) | ((input[\"value\"] & low) << offset)\n",
    "js": "import * as h from \"@graaly/academy\";\n\nexport function solve(input) {\n    let low, mask, offset, width;\n    const tuple_1 = [h.get(input, \"width\"), h.get(input, \"offset\")];\nwidth = h.get(tuple_1, 0);\noffset = h.get(tuple_1, 1);\n    if (h.truth((h.truth(h.not(width)) ? h.not(width) : (h.truth(h.ge(offset, 32)) ? h.ge(offset, 32) : h.gt(width, h.sub(32, offset)))))) {\n        return h.get(input, \"word\");\n    }\n    low = h.sub(h.shl(1, width), 1);\n    mask = h.shl(low, offset);\n    return h.bor(h.band(h.get(input, \"word\"), h.invert(mask)), h.shl(h.band(h.get(input, \"value\"), low), offset));\n}\n",
    "c": "#include <graaly/academy_json.h>\n\nJ *v_solve(J *v_input);\nJ *v_solve(J *v_input) {\n    J *v_low = NULL, *v_mask = NULL, *v_offset = NULL, *v_width = NULL;\n    J *tuple_1 = j_array(2, j_get(v_input, j_str(\"width\"), j_null()), j_get(v_input, j_str(\"offset\"), j_null()));\nv_width = j_get(tuple_1, j_num(0), j_null());\nv_offset = j_get(tuple_1, j_num(1), j_null());\n    if (j_truth((j_truth(j_not(v_width)) ? j_not(v_width) : (j_truth(j_ge(v_offset, j_num(32))) ? j_ge(v_offset, j_num(32)) : j_gt(v_width, j_sub(j_num(32), v_offset)))))) {\n        return j_get(v_input, j_str(\"word\"), j_null());\n    }\n    v_low = j_sub(j_shl(j_num(1), v_width), j_num(1));\n    v_mask = j_shl(v_low, v_offset);\n    return j_bor(j_band(j_get(v_input, j_str(\"word\"), j_null()), j_invert(v_mask)), j_shl(j_band(j_get(v_input, j_str(\"value\"), j_null()), v_low), v_offset));\n}\n\nJ *solve(J *input) { return v_solve(input); }\n"
  },
