    "c": "#include <graaly/academy_json.h>\n\nJ *v_solve(J *v_input);\nJ *v_solve(J *v_input) {\n    J *v_handle = NULL, *v_owned = NULL;\n    v_owned = j_array(0);\n    J *seq_1 = v_input;\n    for (size_t index_1 = 0; index_1 < j_length(seq_1); ++index_1) {\n        v_handle = j_at(seq_1, index_1);\n        if (j_truth((j_truth(j_ne(v_handle, j_num(0))) ? j_not_in(v_handle, v_owned) : j_ne(v_handle, j_num(0))))) {\n            j_append(v_owned, v_handle);\n        }\n    }\n    return j_len(v_owned);\n}\n\nJ *solve(J *input) { return v_solve(input); }\n"
