  "command-tokenizer": {
    "py": "from graaly_academy import *\n\ndef solve(input):\n    out = []\n    token = \"\"\n    quoted = False\n    escaped = False\n    started = False\n    for ch in input[\"text\"]:\n        if escaped:\n            token += ch\n            escaped = False\n            started = True\n        elif ch == \"\\\\\":\n            escaped = True\n            started = True\n        elif ch == '\"':\n            quoted = not quoted\n            started = True\n        elif ch in \" \\t\\r\\n\\v\\f\" and not quoted:\n            if started:\n                out.append(token)\n            token = \"\"\n            started = False\n        else:\n            token += ch\n            started = True\n    if quoted or escaped:\n        return None\n    if started:\n        out.append(token)\n    return out\n",
    "js": "import * as h from \"@graaly/academy\";\n\nexport function solve(input) {\n    let ch, escaped, out, quoted, started, token;\n    out = [];\n    token = \"\";\n    quoted = false;\n    escaped = false;\n    started = false;\n    const seq_1 = h.get(input, \"text\");\n    for (let index_1 = 0; index_1 < seq_1.length; ++index_1) {\n        ch = seq_1[index_1];\n        if (h.truth(escaped)) {\n            token = h.add(token, ch);\n            escaped = false;\n            started = true;\n        } else {\n            if (h.truth(h.eq(ch, \"\\\\\"))) {\n                escaped = true;\n                started = true;\n            } else {\n                if (h.truth(h.eq(ch, \"\\\"\"))) {\n                    quoted = h.not(quoted);\n                    started = true;\n                } else {\n                    if (h.truth((h.truth(h.in(ch, \" \\t\\r\\n\\u000b\\f\")) ? h.not(quoted) : h.in(ch, \" \\t\\r\\n\\u000b\\f\")))) {\n                        if (h.truth(started)) {\n                            h.append(out, token);\n                        }\n                        token = \"\";\n                        started = false;\n                    } else {\n                        token = h.add(token, ch);\n                        started = true;\n                    }\n                }\n            }\n        }\n    }\n    if (h.truth((h.truth(quoted) ? quoted : escaped))) {\n        return null;\n    }\n    if (h.truth(started)) {\n        h.append(out, token);\n    }\n    return out;\n}\n",
    "c": "#include <graaly/academy_json.h>\n\nJ *v_solve(J *v_input);\nJ *v_solve(J *v_input) {\n    J *v_ch = NULL, *v_escaped = NULL, *v_out = NULL, *v_quoted = NULL, *v_started = NULL, *v_token = NULL;\n    v_out = j_array(0);\n    v_token = j_str(\"\");\n    v_quoted = j_bool(0);\n    v_escaped = j_bool(0);\n    v_started = j_bool(0);\n    J *seq_1 = j_get(v_input, j_str(\"text\"), j_null());\n    for (size_t index_1 = 0; index_1 < j_length(seq_1); ++index_1) {\n        v_ch = j_at(seq_1, index_1);\n        if (j_truth(v_escaped)) {\n            v_token = j_add(v_token, v_ch);\n            v_escaped = j_bool(0);\n            v_started = j_bool(1);\n        } else {\n            if (j_truth(j_eq(v_ch, j_str(\"\\\\\")))) {\n                v_escaped = j_bool(1);\n                v_started = j_bool(1);\n            } else {\n                if (j_truth(j_eq(v_ch, j_str(\"\\\"\")))) {\n                    v_quoted = j_not(v_quoted);\n                    v_started = j_bool(1);\n                } else {\n                    if (j_truth((j_truth(j_in(v_ch, j_str(\" \\011\\015\\012\\013\\014\"))) ? j_not(v_quoted) : j_in(v_ch, j_str(\" \\011\\015\\012\\013\\014\"))))) {\n                        if (j_truth(v_started)) {\n                            j_append(v_out, v_token);\n                        }\n                        v_token = j_str(\"\");\n                        v_started = j_bool(0);\n                    } else {\n                        v_token = j_add(v_token, v_ch);\n                        v_started = j_bool(1);\n                    }\n                }\n            }\n        }\n    }\n    if (j_truth((j_truth(v_quoted) ? v_quoted : v_escaped))) {\n        return j_null();\n    }\n    if (j_truth(v_started)) {\n        j_append(v_out, v_token);\n    }\n    return v_out;\n}\n\nJ *solve(J *input) { return v_solve(input); }\n"
  },
