    "c": "#include <graaly/academy_json.h>\n\nJ *v_native_item(J *v_slot, J *v_material, J *v_name, J *v_action, J *v_amount, J *v_durability, J *v_lore);\nJ *v_layout_view(J *v_identifier, J *v_title, J *v_rows, J *v_items, J *v_close);\nJ *v_solve(J *v_input);\nJ *v_native_item(J *v_slot, J *v_material, J *v_name, J *v_action, J *v_amount, J *v_durability, J *v_lore) {\n    return j_object(7, j_str(\"slot\"), v_slot, j_str(\"material\"), v_material, j_str(\"name\"), v_name, j_str(\"actionId\"), v_action, j_str(\"amount\"), j_max(j_num(1), j_min(j_num(64), v_amount)), j_str(\"durability\"), v_durability, j_str(\"lore\"), v_lore);\n}\n\nJ *v_layout_view(J *v_identifier, J *v_title, J *v_rows, J *v_items, J *v_close) {\n    J *v_inventory = NULL, *v_item = NULL, *v_slots = NULL;\n    v_inventory = j_object(4, j_str(\"id\"), v_identifier, j_str(\"title\"), v_title, j_str(\"rows\"), v_rows, j_str(\"items\"), v_items);\n    if (j_truth(v_close)) {\n        j_set(v_inventory, j_str(\"closeActionId\"), v_close);\n    }\n    v_slots = j_object(0);\n    J *seq_1 = v_items;\n    for (size_t index_1 = 0; index_1 < j_length(seq_1); ++index_1) {\n        v_item = j_at(seq_1, index_1);\n        j_set(v_slots, j_str_convert(j_get(v_item, j_str(\"slot\"), j_null())), v_item);\n    }\n    return j_object(3, j_str(\"messages\"), j_array(0), j_str(\"inventory\"), v_inventory, j_str(\"slots\"), v_slots);\n}\n\nJ *v_solve(J *v_input) {\n    J *v_declaration = NULL, *v_declarations = NULL, *v_items = NULL;\n    v_declarations = j_array(3, j_object(4, j_str(\"name\"), j_str(\"Large\"), j_str(\"id\"), j_str(\"large\"), j_str(\"amount\"), j_num(999), j_str(\"material\"), j_str(\"STONE\")), j_object(4, j_str(\"name\"), j_str(\"Small\"), j_str(\"id\"), j_str(\"small\"), j_str(\"amount\"), j_num(0), j_str(\"material\"), j_str(\"STONE\")), j_object(3, j_str(\"name\"), j_str(\"Default\"), j_str(\"id\"), j_str(\"default\"), j_str(\"material\"), j_str(\"BOOK\")));\n    v_items = j_array(0);\n    J *seq_2 = v_declarations;\n    for (size_t index_2 = 0; index_2 < j_length(seq_2); ++index_2) {\n        v_declaration = j_at(seq_2, index_2);\n        j_append(v_items, v_native_item(j_len(v_items), j_get(v_declaration, j_str(\"material\"), j_null()), j_get(v_declaration, j_str(\"name\"), j_null()), j_get(v_declaration, j_str(\"id\"), j_null()), j_get(v_declaration, j_str(\"amount\"), j_num(1)), j_num(0), j_array(0)));\n    }\n    return j_select_paths(v_layout_view(j_str(\"html:3ce2d043\"), j_str(\"Stacks\"), j_num(1), v_items, j_null()), j_get(v_input, j_str(\"paths\"), j_null()));\n}\n\nJ *solve(J *input) { return v_solve(input); }\n"
