  "html-css-source-order": {
    "py": "from graaly_academy import *\n\ndef native_item(slot, material, name, action, amount, durability, lore):\n    return {\"slot\": slot, \"material\": material, \"name\": name, \"actionId\": action, \"amount\": max(1, min(64, amount)), \"durability\": durability, \"lore\": lore}\n\ndef layout_view(identifier, title, rows, items, close):\n    inventory = {\"id\": identifier, \"title\": title, \"rows\": rows, \"items\": items}\n    if close:\n        inventory[\"closeActionId\"] = close\n    slots = {}\n    for item in items:\n        slots[str(item[\"slot\"])] = item\n    return {\"messages\": [], \"inventory\": inventory, \"slots\": slots}\n\ndef solve(input):\n    rules = [\"&9\", \"&c\"]\n    color = rules[-1]\n    items = [native_item(0, \"STONE_BUTTON\", color + \"First\", \"first\", 1, 0, []), native_item(1, \"STONE_BUTTON\", \"&a\" + \"Second\", \"second\", 1, 0, [])]\n    return select_paths(layout_view(\"html:6037b8ba\", \"Order\", 1, items, None), input[\"paths\"])\n",
    "js": "import * as h from \"@graaly/academy\";\n\nfunction native_item(slot, material, name, action, amount, durability, lore) {\n    return h.object([[\"slot\", slot], [\"material\", material], [\"name\", name], [\"actionId\", action], [\"amount\", h.max(1, h.min(64, amount))], [\"durability\", durability], [\"lore\", lore]]);\n}\n\nfunction layout_view(identifier, title, rows, items, close) {\n    let inventory, item, slots;\n    inventory = h.object([[\"id\", identifier], [\"title\", title], [\"rows\", rows], [\"items\", items]]);\n    if (h.truth(close)) {\n        h.set(inventory, \"closeActionId\", close);\n    }\n    slots = h.object([]);\n    const seq_1 = items;\n    for (let index_1 = 0; index_1 < seq_1.length; ++index_1) {\n        item = seq_1[index_1];\n        h.set(slots, h.str(h.get(item, \"slot\")), item);\n    }\n    return h.object([[\"messages\", []], [\"inventory\", inventory], [\"slots\", slots]]);\n}\n\nexport function solve(input) {\n    let color, items, rules;\n    rules = [\"&9\", \"&c\"];\n    color = h.get(rules, h.neg(1));\n    items = [native_item(0, \"STONE_BUTTON\", h.add(color, \"First\"), \"first\", 1, 0, []), native_item(1, \"STONE_BUTTON\", h.add(\"&a\", \"Second\"), \"second\", 1, 0, [])];\n    return h.select_paths(layout_view(\"html:6037b8ba\", \"Order\", 1, items, null), h.get(input, \"paths\"));\n}\n",
    "c": "#include <graaly/academy_json.h>\n\nJ *v_native_item(J *v_slot, J *v_material, J *v_name, J *v_action, J *v_amount, J *v_durability, J *v_lore);\nJ *v_layout_view(J *v_identifier, J *v_title, J *v_rows, J *v_items, J *v_close);\nJ *v_solve(J *v_input);\nJ *v_native_item(J *v_slot, J *v_material, J *v_name, J *v_action, J *v_amount, J *v_durability, J *v_lore) {\n    return j_object(7, j_str(\"slot\"), v_slot, j_str(\"material\"), v_material, j_str(\"name\"), v_name, j_str(\"actionId\"), v_action, j_str(\"amount\"), j_max(j_num(1), j_min(j_num(64), v_amount)), j_str(\"durability\"), v_durability, j_str(\"lore\"), v_lore);\n}\n\nJ *v_layout_view(J *v_identifier, J *v_title, J *v_rows, J *v_items, J *v_close) {\n    J *v_inventory = NULL, *v_item = NULL, *v_slots = NULL;\n    v_inventory = j_object(4, j_str(\"id\"), v_identifier, j_str(\"title\"), v_title, j_str(\"rows\"), v_rows, j_str(\"items\"), v_items);\n    if (j_truth(v_close)) {\n        j_set(v_inventory, j_str(\"closeActionId\"), v_close);\n    }\n    v_slots = j_object(0);\n    J *seq_1 = v_items;\n    for (size_t index_1 = 0; index_1 < j_length(seq_1); ++index_1) {\n        v_item = j_at(seq_1, index_1);\n        j_set(v_slots, j_str_convert(j_get(v_item, j_str(\"slot\"), j_null())), v_item);\n    }\n    return j_object(3, j_str(\"messages\"), j_array(0), j_str(\"inventory\"), v_inventory, j_str(\"slots\"), v_slots);\n}\n\nJ *v_solve(J *v_input) {\n    J *v_color = NULL, *v_items = NULL, *v_rules = NULL;\n    v_rules = j_array(2, j_str(\"&9\"), j_str(\"&c\"));\n    v_color = j_get(v_rules, j_neg(j_num(1)), j_null());\n    v_items = j_array(2, v_native_item(j_num(0), j_str(\"STONE_BUTTON\"), j_add(v_color, j_str(\"First\")), j_str(\"first\"), j_num(1), j_num(0), j_array(0)), v_native_item(j_num(1), j_str(\"STONE_BUTTON\"), j_add(j_str(\"&a\"), j_str(\"Second\")), j_str(\"second\"), j_num(1), j_num(0), j_array(0)));\n    return j_select_paths(v_layout_view(j_str(\"html:6037b8ba\"), j_str(\"Order\"), j_num(1), v_items, j_null()), j_get(v_input, j_str(\"paths\"), j_null()));\n}\n\nJ *solve(J *input) { return v_solve(input); }\n"
  },
