    "js": "import * as h from \"@graaly/academy\";\n\nfunction native_item(slot, material, name, action, amount, durability, lore) {\n    return h.object([[\"slot\", slot], [\"material\", material], [\"name\", name], [\"actionId\", action], [\"amount\", h.max(1, h.min(64, amount))], [\"durability\", durability], [\"lore\", lore]]);\n}\n\nfunction layout_view(identifier, title, rows, items, close) {\n    let inventory, item, slots;\n    inventory = h.object([[\"id\", identifier], [\"title\", title], [\"rows\", rows], [\"items\", items]]);\n    if (h.truth(close)) {\n        h.set(inventory, \"closeActionId\", close);\n    }\n    slots = h.object([]);\n    const seq_1 = items;\n    for (let index_1 = 0; index_1 < seq_1.length; ++index_1) {\n        item = seq_1[index_1];\n        h.set(slots, h.str(h.get(item, \"slot\")), item);\n    }\n    return h.object([[\"messages\", []], [\"inventory\", inventory], [\"slots\", slots]]);\n}\n\nexport function solve(input) {\n    let declaration, declarations, items;\n    declarations = [h.object([[\"name\", \"Hidden\"], [\"hidden\", true], [\"action\", null]]), h.object([[\"name\", \"First\"], [\"hidden\", false], [\"action\", \"first\"]]), h.object([[\"name\", \"Second\"], [\"hidden\", false], [\"action\", \"second\"]])];\n    items = [];\n    const seq_2 = declarations;\n    for (let index_2 = 0; index_2 < seq_2.length; ++index_2) {\n        declaration = seq_2[index_2];\n        if (h.truth(h.not(h.get(declaration, \"hidden\")))) {\n            h.append(items, native_item(h.len(items), \"STONE_BUTTON\", h.get(declaration, \"name\"), h.get(declaration, \"action\"), 1, 0, []));\n        }\n    }\n    return h.select_paths(layout_view(\"menu\", \"Menu\", 1, items, null), h.get(input, \"paths\"));\n}\n",
