  "packet-health-reencode": {
    "py": "from graaly_academy import *\n\ndef solve(input):\n    out = []\n    for action in input[\"actions\"]:\n        if action[\"kind\"] != \"packet\" or get(action, \"direction\") != \"send\" or action[\"name\"] != \"Play.Server.UPDATE_HEALTH\":\n            continue\n        health = max(0, min(20, action[\"data\"][\"health\"]))\n        if health != action[\"data\"][\"health\"]:\n            data = clone(action[\"data\"])\n            data[\"health\"] = health\n            out.append([\"packet.reencode\", action[\"name\"], data])\n    return out\n",
    "js": "import * as h from \"@graaly/academy\";\n\nexport function solve(input) {\n    let action, data, health, out;\n    out = [];\n    const seq_1 = h.get(input, \"actions\");\n    for (let index_1 = 0; index_1 < seq_1.length; ++index_1) {\n        action = seq_1[index_1];\n        if (h.truth((h.truth(h.ne(h.get(action, \"kind\"), \"packet\")) ? h.ne(h.get(action, \"kind\"), \"packet\") : (h.truth(h.ne(h.get(action, \"direction\"), \"send\")) ? h.ne(h.get(action, \"direction\"), \"send\") : h.ne(h.get(action, \"name\"), \"Play.Server.UPDATE_HEALTH\"))))) {\n            continue;\n        }\n        health = h.max(0, h.min(20, h.get(h.get(action, \"data\"), \"health\")));\n        if (h.truth(h.ne(health, h.get(h.get(action, \"data\"), \"health\")))) {\n            data = h.clone(h.get(action, \"data\"));\n            h.set(data, \"health\", health);\n            h.append(out, [\"packet.reencode\", h.get(action, \"name\"), data]);\n        }\n    }\n    return out;\n}\n",
    "c": "#include <graaly/academy_json.h>\n\nJ *v_solve(J *v_input);\nJ *v_solve(J *v_input) {\n    J *v_action = NULL, *v_data = NULL, *v_health = NULL, *v_out = NULL;\n    v_out = j_array(0);\n    J *seq_1 = j_get(v_input, j_str(\"actions\"), j_null());\n    for (size_t index_1 = 0; index_1 < j_length(seq_1); ++index_1) {\n        v_action = j_at(seq_1, index_1);\n        if (j_truth((j_truth(j_ne(j_get(v_action, j_str(\"kind\"), j_null()), j_str(\"packet\"))) ? j_ne(j_get(v_action, j_str(\"kind\"), j_null()), j_str(\"packet\")) : (j_truth(j_ne(j_get(v_action, j_str(\"direction\"), j_null()), j_str(\"send\"))) ? j_ne(j_get(v_action, j_str(\"direction\"), j_null()), j_str(\"send\")) : j_ne(j_get(v_action, j_str(\"name\"), j_null()), j_str(\"Play.Server.UPDATE_HEALTH\")))))) {\n            continue;\n        }\n        v_health = j_max(j_num(0), j_min(j_num(20), j_get(j_get(v_action, j_str(\"data\"), j_null()), j_str(\"health\"), j_null())));\n        if (j_truth(j_ne(v_health, j_get(j_get(v_action, j_str(\"data\"), j_null()), j_str(\"health\"), j_null())))) {\n            v_data = j_clone(j_get(v_action, j_str(\"data\"), j_null()));\n            j_set(v_data, j_str(\"health\"), v_health);\n            j_append(v_out, j_array(3, j_str(\"packet.reencode\"), j_get(v_action, j_str(\"name\"), j_null()), v_data));\n        }\n    }\n    return v_out;\n}\n\nJ *solve(J *input) { return v_solve(input); }\n"
  },
