  "python-context-cleanup": {
    "py": "from graaly_academy import *\n\ndef solve(input):\n    trace = [\"open\", \"work\"]\n    if input[\"fail\"]:\n        trace.append(\"close\")\n        trace.append(\"handled\")\n    else:\n        trace.append(\"commit\")\n        trace.append(\"close\")\n    return trace\n",
    "js": "import * as h from \"@graaly/academy\";\n\nexport function solve(input) {\n    let trace;\n    trace = [\"open\", \"work\"];\n    if (h.truth(h.get(input, \"fail\"))) {\n        h.append(trace, \"close\");\n        h.append(trace, \"handled\");\n    } else {\n        h.append(trace, \"commit\");\n        h.append(trace, \"close\");\n    }\n    return trace;\n}\n",
    "c": "#include <graaly/academy_json.h>\n\nJ *v_solve(J *v_input);\nJ *v_solve(J *v_input) {\n    J *v_trace = NULL;\n    v_trace = j_array(2, j_str(\"open\"), j_str(\"work\"));\n    if (j_truth(j_get(v_input, j_str(\"fail\"), j_null()))) {\n        j_append(v_trace, j_str(\"close\"));\n        j_append(v_trace, j_str(\"handled\"));\n    } else {\n        j_append(v_trace, j_str(\"commit\"));\n        j_append(v_trace, j_str(\"close\"));\n    }\n    return v_trace;\n}\n\nJ *solve(J *input) { return v_solve(input); }\n"
  },
