    "js": "import * as h from \"@graaly/academy\";\n\nfunction native_item(slot, material, name, amount) {\n    return h.object([[\"slot\", slot], [\"material\", material], [\"name\", name], [\"amount\", amount], [\"durability\", 0], [\"lore\", []]]);\n}\n\nfunction native_inventory(title, items) {\n    return h.object([[\"title\", title], [\"rows\", 1], [\"items\", items]]);\n}\n\nfunction latest_props(input) {\n    let action, props;\n    props = h.get(input, \"props\");\n    const seq_1 = h.get(input, \"actions\");\n    for (let index_1 = 0; index_1 < seq_1.length; ++index_1) {\n        action = seq_1[index_1];\n        if (h.truth(h.eq(h.get(action, \"kind\"), \"rerender\"))) {\n            props = h.get(action, \"props\");\n        }\n    }\n    return props;\n}\n\nexport function solve(input) {\n    let action, active, next, props;\n    props = h.get(input, \"props\");\n    active = 1;\n    const seq_2 = h.get(input, \"actions\");\n    for (let index_2 = 0; index_2 < seq_2.length; ++index_2) {\n        action = seq_2[index_2];\n        if (h.truth(h.eq(h.get(action, \"kind\"), \"rerender\"))) {\n            next = h.get(action, \"props\");\n            if (h.truth(h.ne(h.get(next, \"channel\"), h.get(props, \"channel\")))) {\n                active = h.sub(active, 1);\n                active = h.add(active, 1);\n            }\n            props = next;\n        }\n    }\n    return h.select_paths(h.object([[\"tab\", h.object([[\"header\", h.str(active)], [\"footer\", h.get(props, \"channel\")]])]]), h.get(input, \"paths\"));\n}\n",
    "c": "#include <graaly/academy_json.h>\n\nJ *v_native_item(J *v_slot, J *v_material, J *v_name, J *v_amount);\nJ *v_native_inventory(J *v_title, J *v_items);\nJ *v_latest_props(J *v_input);\nJ *v_solve(J *v_input);\nJ *v_native_item(J *v_slot, J *v_material, J *v_name, J *v_amount) {\n    return j_object(6, j_str(\"slot\"), v_slot, j_str(\"material\"), v_material, j_str(\"name\"), v_name, j_str(\"amount\"), v_amount, j_str(\"durability\"), j_num(0), j_str(\"lore\"), j_array(0));\n}\n\nJ *v_native_inventory(J *v_title, J *v_items) {\n    return j_object(3, j_str(\"title\"), v_title, j_str(\"rows\"), j_num(1), j_str(\"items\"), v_items);\n}\n\nJ *v_latest_props(J *v_input) {\n    J *v_action = NULL, *v_props = NULL;\n    v_props = j_get(v_input, j_str(\"props\"), j_null());\n    J *seq_1 = j_get(v_input, j_str(\"actions\"), j_null());\n    for (size_t index_1 = 0; index_1 < j_length(seq_1); ++index_1) {\n        v_action = j_at(seq_1, index_1);\n        if (j_truth(j_eq(j_get(v_action, j_str(\"kind\"), j_null()), j_str(\"rerender\")))) {\n            v_props = j_get(v_action, j_str(\"props\"), j_null());\n        }\n    }\n    return v_props;\n}\n\nJ *v_solve(J *v_input) {\n    J *v_action = NULL, *v_active = NULL, *v_next = NULL, *v_props = NULL;\n    v_props = j_get(v_input, j_str(\"props\"), j_null());\n    v_active = j_num(1);\n    J *seq_2 = j_get(v_input, j_str(\"actions\"), j_null());\n    for (size_t index_2 = 0; index_2 < j_length(seq_2); ++index_2) {\n        v_action = j_at(seq_2, index_2);\n        if (j_truth(j_eq(j_get(v_action, j_str(\"kind\"), j_null()), j_str(\"rerender\")))) {\n            v_next = j_get(v_action, j_str(\"props\"), j_null());\n            if (j_truth(j_ne(j_get(v_next, j_str(\"channel\"), j_null()), j_get(v_props, j_str(\"channel\"), j_null())))) {\n                v_active = j_sub(v_active, j_num(1));\n                v_active = j_add(v_active, j_num(1));\n            }\n            v_props = v_next;\n        }\n    }\n    return j_select_paths(j_object(1, j_str(\"tab\"), j_object(2, j_str(\"header\"), j_str_convert(v_active), j_str(\"footer\"), j_get(v_props, j_str(\"channel\"), j_null()))), j_get(v_input, j_str(\"paths\"), j_null()));\n}\n\nJ *solve(J *input) { return v_solve(input); }\n"
